mapper.update:
update proj_project
project_code = #{projectCode}, project_name = #{projectName}, engineering_project = #{engineeringProject}, project_category_id = #{projectCategoryId}, client_unit = #{clientUnit}, client_unit_nature = #{clientUnitNature}, contact_name = #{contactName}, contact_phone = #{contactPhone}, project_location = #{projectLocation}, contract_id = #{contractId}, data_source = #{dataSource}, status = #{status}, project_nature = #{projectNature}, assign_date = #{assignDate}, duration_require = #{durationRequire}, total_duration = #{totalDuration}, extra_data = #{extraData}::jsonb, related_project_id = #{relatedProjectId}, related_project_code_text = #{relatedProjectCodeText}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

update proj_project set status = #{status},
    close_time = case when #{status} = 'closed' then now() else close_time end,
    update_time = now() where id = #{id}

mapper.select:
select count(1) filter (where exists ( select 1 from proj_workload w where w.project_id = p.id and w.del_flag = '0')) as "workloadDone", count(1) filter (where not exists ( select 1 from proj_workload w where w.project_id = p.id and w.del_flag = '0')) as "workloadUndone", count(1) filter (where exists ( select 1 from proj_payment pm where pm.project_id = p.id and pm.del_flag = '0' and pm.payment_type in ('advance', 'final'))) as "paymentDone", count(1) filter (where not exists ( select 1 from proj_payment pm where pm.project_id = p.id and pm.del_flag = '0' and pm.payment_type in ('advance', 'final'))) as "paymentUndone", count(1) filter (where exists ( select 1 from proj_payment pm where pm.project_id = p.id and pm.del_flag = '0' and (pm.invoice_date is not null or (pm.invoice_amount is not null and pm.invoice_amount > 0))) and not exists ( select 1 from proj_payment pm2 where pm2.project_id = p.id and pm2.del_flag = '0' and pm2.payment_type in ('advance', 'final') and pm2.amount is not null and pm2.amount > 0)) as "invoiceUnpaid" from proj_project p where p.del_flag = '0'
AND (p.project_code like concat('%', #{keyword}, '%') OR p.project_name like concat('%', #{keyword}, '%') OR p.client_unit like concat('%', #{keyword}, '%') OR p.engineering_project like concat('%', #{keyword}, '%') OR p.contact_name like concat('%', #{keyword}, '%') OR p.project_location like concat('%', #{keyword}, '%'))
AND p.contact_name like concat('%', #{contactName}, '%')
AND p.contact_phone like concat('%', #{contactPhone}, '%')
AND p.project_location like concat('%', #{projectLocation}, '%')
AND EXISTS (select 1 from proj_leader l where l.project_id = p.id and l.user_id = #{leaderId} and l.del_flag = '0')
AND p.assign_date >= to_date(#{assignDateBegin}, 'YYYY-MM-DD')
AND p.assign_date <= to_date(#{assignDateEnd}, 'YYYY-MM-DD')
AND p.project_code like concat('%', #{projectCode}, '%')
AND p.project_name like concat('%', #{projectName}, '%')
AND p.engineering_project like concat('%', #{engineeringProject}, '%')
AND p.project_category_id = #{projectCategoryId}
AND p.project_category_id in
#{cid}
AND p.client_unit like concat('%', #{clientUnit}, '%')
AND p.contract_id = #{contractId}
AND p.status = #{status}
AND p.project_nature = #{projectNature}
AND p.client_unit_nature = #{clientUnitNature}
AND p.status in
#{s}
AND p.data_source = #{dataSource}
AND p.close_time >= to_date(#{closeDateBegin}, 'YYYY-MM-DD')
AND p.close_time < to_date(#{closeDateEnd}, 'YYYY-MM-DD') + interval '1 day'
AND >= to_date(#{newDateBegin}, 'YYYY-MM-DD')
AND < to_date(#{newDateEnd}, 'YYYY-MM-DD') + interval '1 day'
